package com.lqq.supportflow.action.application;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import com.lqq.supportflow.action.domain.ActionExecutionPort; import com.lqq.supportflow.eventing.*; import org.springframework.context.event.EventListener; import org.springframework.stereotype.Service;
@Service public class ExecuteApprovedActionService { private final ActionExecutionPort executions; private final EventConsumerService consumers; private final ObjectMapper json; public ExecuteApprovedActionService(ActionExecutionPort executions,EventConsumerService consumers,ObjectMapper json){this.executions=executions;this.consumers=consumers;this.json=json;} @EventListener public void on(PublishedOutboxEvent event) throws Exception {if(!"approval.approved".equals(event.eventType())||!consumers.claim(event.tenantId(),"approved-action-executor",event.id()))return;JsonNode payload=json.readTree(event.payload());String actionType=payload.path("actionType").asText();if(!"refund.request".equals(actionType)&&!"compensation.issue".equals(actionType))return;executions.executeOnce(event.tenantId(),payload.path("approvalId").asLong(),actionType);}}
